pair A, B, C, D, E, F, G, H;

A = (1,0);
B = (-1,0);
C = (0,1);
D = (0,-1);
E = (1 + sqrt(3))/2*(1,1);
F = (1 + sqrt(3))/2*(-1,-1);
G = (1 + sqrt(3))/2*(1,-1);
